  const role = _permRoleOf(p);
  const overrides = (state._compExtras && state._compExtras.permScopes) || {};
  const v = (overrides[role] && overrides[role][scopeId]) || (PERM_SCOPE_DEFAULTS[role] || {})[scopeId];
