const isOfficeStaffRole = (r) => r === 'rep_office' || r === 'rep_office_lead' || r === 'rep_loyalty' || r === 'rep_loyalty_lead' || r === 'office_staff'
  || (r === 'rep' && crmSellerIs('office_staff', state.myRepType || ''));

