  try { state._indicatorSettingsSavedAt = (JSON.parse(localStorage.getItem(INDICATORS_SETTINGS_STORAGE_KEY) || 'null') || {}).savedAt || ''; }
  catch { state._indicatorSettingsSavedAt = ''; }
