const REPORTING_MONTH_ABBR = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const reportingMonthLbl = (ym) => { const [y, m] = ym.split('-'); return REPORTING_MONTH_ABBR[Number(m) - 1] + " '" + y.slice(2); };

