      const _drill = (rs) => openReportingDrillModal({ chartTitle: 'CRM fixes \u00b7 ' + tag, sliceLabel: rs.length + ' account' + (rs.length === 1 ? '' : 's') + ' \u00b7 newest first', rows: rs, formatValue: fmt.usd0 });
