const MKP_GROUPS = [['Google Ads', ['Google Ads', 'Google Local Services']], ['Meta Ads', ['Facebook']], ['Organic', ['Organic', 'PestBooker', 'Click-To-Buy']], ['Referral', ['Referral']]];
