  prod_per_appt:   { RIDD: 159.76, Atlanta: 158.02, Charleston: 163.64, Destin: 163.4, 'Myrtle Beach': 167.12, Raleigh: 152.9, 'Salt Lake': 128.27, 'Virginia Beach': 156.57 },
