        const setRule = (k, f, v) => saveAL({ approval: Object.assign({}, AP, { [k]: Object.assign({ appt: ruleOf(k, 'appt'), autopay: ruleOf(k, 'autopay'), signed: ruleOf(k, 'signed') }, AP[k] || {}, { [f]: v }) }) });
