  const push = (id, name, group) => { if (!seen.has(id)) { seen.add(id); out.push({ id, name, group }); } };
  try { (getIndicatorCompetitions() || []).forEach(c => push(c.id, c.name, 'Sales Reps')); } catch (e) { /* no config yet */ }
  push('kobe_week', 'Kobe Week', 'Sales Reps');
